node -e "
const fs = require('fs');
const path = require('path');
try {
  const memFile = path.join(process.cwd(), '.claude', 'memory', 'project.json');
  if (fs.existsSync(memFile)) {
    const mem = JSON.parse(fs.readFileSync(memFile, 'utf8'));
    mem.last_session = new Date().toISOString();
    fs.writeFileSync(memFile, JSON.stringify(mem, null, 2));
  }
} catch (e) {}
const logFile = path.join(process.env.HOME, '.claude', 'omnipus-ledger.jsonl');
try { fs.appendFileSync(logFile, JSON.stringify({ event: 'Stop', ts: new Date().toISOString(), session: process.env.CLAUDE_SESSION_ID || 'unknown', cwd: process.cwd() }) + '\n'); } catch (e) {}
" 2>/dev/null || true

node -e "
const fs = require('fs');
let raw = '';
try { raw = fs.readFileSync(0, 'utf8'); } catch (e) {}
try {
  const data = JSON.parse(raw);
  const cmd = (data.tool_input && data.tool_input.command) || '';
  const blocked = ['rm -rf /', 'rm -rf ~', 'dd if=', 'mkfs', ':(){:|:&};:'];
  if (blocked.some(b => cmd.includes(b))) {
    console.log(JSON.stringify({ decision: 'block', reason: 'Omnipus safety: destructive command blocked — ' + cmd.slice(0, 80) }));
  }
} catch (e) {}
" 2>/dev/null || true
